from pathlib import Path
import re

p=Path('apps/Sports-Info/Sports Info.js')
s=p.read_text(encoding='utf-8')

assert 'const APP_VERSION = "2.5.12";' in s
s=s.replace('// Sports Info v2.5.12','// Sports Info v2.5.15',1)
s=s.replace('const APP_VERSION = "2.5.12";','const APP_VERSION = "2.5.15";',1)

# Layout defaults + deep merge / validation
old_defaults='const DEFAULTS={language:null,sportId:"football",leagueId:"cze.1",teamId:"",teamName:"",showLive:true,showLast:true,showNext:true,showTable:true,showForm:true,showLogos:true,maxMatches:4,theme:"auto",accent:"#38bdf8",background:"#0b1020",panelColor:"#111827",textColor:"#f8fafc",mutedColor:"#94a3b8",liveColor:"#f87171",winColor:"#86efac",compact:false,refreshMinutes:15,apiEspnBase:"https://site.api.espn.com",apiFotmobBase:"https://www.fotmob.com/api/data",apiOneFootballFeedBase:"https://feedmonster.onefootball.com",apiOneFootballScoresBase:"https://api.onefootball.com",apiSofaBase:"https://api.sofascore.com/api/v1",apiSportsApiBase:"https://v2.floorball.sportsapipro.com",sportsApiKey:""};'
assert old_defaults in s
new_defaults='''const LAYOUT_DEFAULTS={\n  small:{teamWidth:64,scoreWidth:18,teamFont:9,scoreFont:15,logoSize:12,logoGap:3,cardPaddingX:0,teamAlign:"edge"},\n  medium:{teamWidth:128,scoreWidth:40,teamFont:11,scoreFont:20,logoSize:17,logoGap:5,cardPaddingX:10,teamAlign:"center",listDateWidth:40,listTeamWidth:106,listScoreWidth:54},\n  large:{teamWidth:128,scoreWidth:44,teamFont:11,scoreFont:20,logoSize:17,logoGap:5,cardPaddingX:10,teamAlign:"center",listDateWidth:40,listTeamWidth:106,listScoreWidth:54,tableTeamWidth:110,tableWideWidth:30,tableNarrowWidth:23,tableHeaderFont:8,tableFont:10,tableTeamFont:11,tableAlign:"center"}\n};\nconst DEFAULTS={language:null,sportId:"football",leagueId:"cze.1",teamId:"",teamName:"",showLive:true,showLast:true,showNext:true,showTable:true,showForm:true,showLogos:true,maxMatches:4,theme:"auto",accent:"#38bdf8",background:"#0b1020",panelColor:"#111827",textColor:"#f8fafc",mutedColor:"#94a3b8",liveColor:"#f87171",winColor:"#86efac",compact:false,refreshMinutes:15,layout:LAYOUT_DEFAULTS,apiEspnBase:"https://site.api.espn.com",apiFotmobBase:"https://www.fotmob.com/api/data",apiOneFootballFeedBase:"https://feedmonster.onefootball.com",apiOneFootballScoresBase:"https://api.onefootball.com",apiSofaBase:"https://api.sofascore.com/api/v1",apiSportsApiBase:"https://v2.floorball.sportsapipro.com",sportsApiKey:""};'''
s=s.replace(old_defaults,new_defaults,1)

old_merge=re.search(r'function merge\(raw\)\{.*?return s\}',s,re.S)
assert old_merge
new_merge='''function merge(raw){\n  const input=raw||{},s=Object.assign(clone(DEFAULTS),input);\n  s.layout=clone(LAYOUT_DEFAULTS);\n  for(const family of ["small","medium","large"])Object.assign(s.layout[family],input.layout?.[family]||{});\n  if(!["cs","en","de","es"].includes(s.language))s.language=null;if(!SPORTS.some(x=>x.id===s.sportId))s.sportId=DEFAULTS.sportId;const ls=leaguesForSport(s.sportId);if(!ls.some(x=>x.id===s.leagueId))s.leagueId=ls[0]?.id||DEFAULTS.leagueId;s.maxMatches=clamp(Number(s.maxMatches)||4,1,8);s.refreshMinutes=clamp(Number(s.refreshMinutes)||15,5,60);if(!["auto","dark","light","custom"].includes(s.theme))s.theme="auto";for(const k of["accent","background","panelColor","textColor","mutedColor","liveColor","winColor"])if(!/^#[0-9a-fA-F]{6}$/.test(String(s[k]||"")))s[k]=DEFAULTS[k];\n  const ranges={teamWidth:[48,150],scoreWidth:[14,70],teamFont:[7,15],scoreFont:[10,26],logoSize:[8,24],logoGap:[0,10],cardPaddingX:[0,18],listDateWidth:[30,60],listTeamWidth:[72,135],listScoreWidth:[36,70],tableTeamWidth:[82,135],tableWideWidth:[24,38],tableNarrowWidth:[18,32],tableHeaderFont:[7,12],tableFont:[8,14],tableTeamFont:[9,14]};\n  for(const family of ["small","medium","large"]){const L=s.layout[family];for(const [k,r] of Object.entries(ranges))if(k in L)L[k]=clamp(Number(L[k])||LAYOUT_DEFAULTS[family][k]||r[0],r[0],r[1]);if(!["edge","center","left","right"].includes(L.teamAlign))L.teamAlign=LAYOUT_DEFAULTS[family].teamAlign;if(family==="large"&&!['center','right'].includes(L.tableAlign))L.tableAlign='center'}\n  for(const k of["apiEspnBase","apiFotmobBase","apiSofaBase","apiSportsApiBase"])s[k]=String(s[k]||DEFAULTS[k]).replace(/\\/+$/,"");s.sportsApiKey=String(s.sportsApiKey||"").trim();return s\n}'''
s=s[:old_merge.start()]+new_merge+s[old_merge.end():]

# Per-size layout helpers + team cells / match cards / list rows
old_team=re.search(r'function teamLabel\(t,family\)\{.*?\n\}\nasync function teamCell\(parent,t,s,p,family,right=false,width=0\)\{.*?\n\}\nasync function matchCard\(parent,e,s,p,family="medium"\)\{.*?\n\}',s,re.S)
assert old_team
new_team='''function layoutFor(s,family){return s.layout?.[family]||LAYOUT_DEFAULTS[family]||LAYOUT_DEFAULTS.medium}\nfunction teamLabel(t,family,width=0,font=10,withLogo=false){\n  const full=t.name||t.short||t.abbr||"",short=t.short&&t.short!==full?t.short:(t.abbr||full);\n  if(family!=="small")return full.length<=22?full:short;\n  if(!width)return full;\n  const usable=Math.max(24,width-(withLogo?18:0)),estimate=full.length*font*.58;\n  if(estimate<=usable*2)return full;\n  return short||full\n}\nfunction teamSpacerMode(side,L){if(L.teamAlign==="edge")return side==="away";if(L.teamAlign==="left")return false;if(L.teamAlign==="right")return true;return side==="home"}\nasync function teamCell(parent,t,s,p,family,side="home",width=0){\n  const L=layoutFor(s,family),right=teamSpacerMode(side,L),r=parent.addStack();r.layoutHorizontally();r.centerAlignContent();if(width)r.size=new Size(width,0);if(right)r.addSpacer();\n  let hasLogo=false;if(s.showLogos){const i=await logo(t.logo,t.id||t.abbr);if(i){const v=r.addImage(i);v.imageSize=new Size(L.logoSize,L.logoSize);r.addSpacer(L.logoGap);hasLogo=true}}\n  const z=txt(r,teamLabel(t,family,width,L.teamFont,hasLogo),L.teamFont,p.text,true);z.lineLimit=family==="small"?2:1;z.minimumScaleFactor=1;if(!right)r.addSpacer()\n}\nasync function matchCard(parent,e,s,p,family="medium"){\n  const L=layoutFor(s,family),b=parent.addStack();b.layoutVertically();b.backgroundColor=p.panel;b.cornerRadius=14;b.setPadding(family==="small"?8:10,L.cardPaddingX,family==="small"?8:10,L.cardPaddingX);\n  const h=b.addStack();h.layoutHorizontally();txt(h,state(s,e),9,e.state==="in"?p.live:p.muted,true);h.addSpacer();if(e.state==="in")txt(h,"●",9,p.live,true);\n  b.addSpacer(family==="small"?5:7);const r=b.addStack();r.layoutHorizontally();r.centerAlignContent();\n  await teamCell(r,e.home,s,p,family,"home",L.teamWidth);r.addSpacer();\n  const mid=r.addStack();mid.layoutHorizontally();mid.centerAlignContent();mid.size=new Size(L.scoreWidth,0);mid.addSpacer();const sc=txt(mid,score(e),L.scoreFont,p.text,true);sc.centerAlignText();mid.addSpacer();\n  r.addSpacer();await teamCell(r,e.away,s,p,family,"away",L.teamWidth)\n}'''
s=s[:old_team.start()]+new_team+s[old_team.end():]

old_line=re.search(r'async function line\(parent,e,s,p,family="large"\)\{.*?\}',s,re.S)
assert old_line
new_line='''async function line(parent,e,s,p,family="large"){const L=layoutFor(s,family),r=parent.addStack();r.layoutHorizontally();r.centerAlignContent();const dateW=L.listDateWidth||40,teamW=L.listTeamWidth||106,scoreW=L.listScoreWidth||54;lineCell(r,day(s,e.date),dateW,p.muted,"left",true,9,.8);lineCell(r,teamLabel(e.home,family,teamW,10,false),teamW,p.text,"right",true,10,1);lineCell(r,score(e)==="–"?time(s,e.date):score(e),scoreW,e.state==="in"?p.live:p.text,"center",true,10,1);lineCell(r,teamLabel(e.away,family,teamW,10,false),teamW,p.text,"left",true,10,1)}'''
s=s[:old_line.start()]+new_line+s[old_line.end():]

# Standings: one max-7-slot system. The 7-slot grid width is fixed; fewer stats expand to consume the same space.
old_profiles=re.search(r'const TABLE_PROFILES=\{.*?\n\};',s,re.S)
assert old_profiles
new_profiles='''const TABLE_PROFILES={\n  football:[["team","TÝM"],["played","Z"],["wins","V"],["draws","R"],["losses","P"],["score","SK"],["diff","RS"],["points","B"]],\n  hockey:[["team","TÝM"],["played","Z"],["wins","V"],["otWins","VP"],["otLosses","PP"],["losses","P"],["score","SK"],["points","B"]],\n  basketball:[["team","TÝM"],["played","Z"],["wins","V"],["losses","P"],["pct","%"],["score","SK"]],\n  floorball:[["team","TÝM"],["played","Z"],["wins","V"],["draws","R"],["losses","P"],["score","SK"],["points","B"]],\n  baseball:[["team","TÝM"],["played","Z"],["wins","W"],["losses","L"],["pct","PCT"],["gb","GB"]]\n};\nfunction tableSlotLayout(s,cols){\n  const L=layoutFor(s,"large"),stats=cols.slice(1,8),wide=L.tableWideWidth,narrow=L.tableNarrowWidth,total=4*wide+3*narrow,base=stats.reduce((a,_,i)=>a+(i<4?wide:narrow),0),scale=base?total/base:1;\n  const statCols=stats.map(([key,label],i)=>[key,label,Math.max(18,Math.floor((i<4?wide:narrow)*scale))]);\n  const used=statCols.reduce((a,c)=>a+c[2],0);if(statCols.length)statCols[statCols.length-1][2]+=total-used;\n  return {teamCol:[cols[0][0],cols[0][1],L.tableTeamWidth],statCols,statsWidth:total}\n}'''
s=s[:old_profiles.start()]+new_profiles+s[old_profiles.end():]

s=s.replace('const cols=TABLE_PROFILES[s.sportId]||TABLE_PROFILES.football,teamCol=cols[0],statCols=cols.slice(1),statsWidth=statCols.reduce((a,c)=>a+c[2],0);','const cols=TABLE_PROFILES[s.sportId]||TABLE_PROFILES.football,{teamCol,statCols,statsWidth}=tableSlotLayout(s,cols),TL=layoutFor(s,"large");',1)
s=s.replace('const t=txt(c,label,8,p.muted,true);t.lineLimit=1;t.minimumScaleFactor=1;c.addSpacer()','const t=txt(c,label,TL.tableHeaderFont,p.muted,true);t.lineLimit=1;t.minimumScaleFactor=1;c.addSpacer()',1)
s=s.replace('for(const [key,label,width] of statCols)lineCell(hs,label,width,p.muted,"center",true,8,.8);','for(const [key,label,width] of statCols)lineCell(hs,label,width,p.muted,TL.tableAlign,true,TL.tableHeaderFont,1);',1)
s=s.replace('const t=txt(c,standingValue(x,key),11,color,fav);t.lineLimit=1;t.minimumScaleFactor=.85;c.addSpacer()','const t=txt(c,standingValue(x,key),TL.tableTeamFont,color,fav);t.lineLimit=1;t.minimumScaleFactor=.8;c.addSpacer()',1)
s=s.replace('for(const [key,,width] of statCols){const color=fav?p.accent:p.muted;lineCell(rs,standingValue(x,key),width,color,"center",fav||key==="points",10,.8)}','for(const [key,,width] of statCols){const color=fav?p.accent:p.muted;lineCell(rs,standingValue(x,key),width,color,TL.tableAlign,fav||key==="points",TL.tableFont,1)}',1)

# Settings UI helpers / translations
insert='''\nconst LAYOUT_TEXT={\ncs:{layout:"Layout",layoutSub:"Každá velikost widgetu má vlastní nastavení.",small:"Small",medium:"Medium",large:"Large",teamWidth:"Šířka týmu",scoreWidth:"Šířka skóre",teamFont:"Velikost názvu týmu",scoreFont:"Velikost skóre",logoSize:"Velikost loga",logoGap:"Mezera za logem",cardPaddingX:"Vnitřní boční odsazení",teamAlign:"Zarovnání týmů",edge:"K okrajům",center:"Ke středu",left:"Vlevo",right:"Vpravo",dateWidth:"Šířka data",listTeamWidth:"Šířka týmu v seznamu",listScoreWidth:"Šířka skóre v seznamu",table:"Tabulka",tableTeamWidth:"Šířka sloupce TÝM",wideWidth:"Šířka prvních 4 statistik",narrowWidth:"Šířka posledních 3 statistik",headerFont:"Velikost hlavičky",tableFont:"Velikost statistik",tableTeamFont:"Velikost názvu týmu v tabulce",tableAlign:"Zarovnání statistik",reset:"Obnovit výchozí Layout",preview:"Náhled této velikosti"},\nen:{layout:"Layout",layoutSub:"Each widget size has its own independent layout settings.",small:"Small",medium:"Medium",large:"Large",teamWidth:"Team width",scoreWidth:"Score width",teamFont:"Team name size",scoreFont:"Score size",logoSize:"Logo size",logoGap:"Logo gap",cardPaddingX:"Card side padding",teamAlign:"Team alignment",edge:"To edges",center:"To center",left:"Left",right:"Right",dateWidth:"Date width",listTeamWidth:"List team width",listScoreWidth:"List score width",table:"Standings",tableTeamWidth:"TEAM column width",wideWidth:"First 4 stat widths",narrowWidth:"Last 3 stat widths",headerFont:"Header font",tableFont:"Stats font",tableTeamFont:"Table team font",tableAlign:"Stats alignment",reset:"Reset default layout",preview:"Preview this size"},\nde:{layout:"Layout",layoutSub:"Jede Widget-Größe hat eigene Layout-Einstellungen.",small:"Small",medium:"Medium",large:"Large",teamWidth:"Team-Breite",scoreWidth:"Ergebnis-Breite",teamFont:"Team-Schrift",scoreFont:"Ergebnis-Schrift",logoSize:"Logo-Größe",logoGap:"Logo-Abstand",cardPaddingX:"Seitlicher Innenabstand",teamAlign:"Team-Ausrichtung",edge:"Zu den Rändern",center:"Zur Mitte",left:"Links",right:"Rechts",dateWidth:"Datum-Breite",listTeamWidth:"Team-Breite Liste",listScoreWidth:"Ergebnis-Breite Liste",table:"Tabelle",tableTeamWidth:"TEAM-Spalte",wideWidth:"Erste 4 Statistikspalten",narrowWidth:"Letzte 3 Statistikspalten",headerFont:"Kopfzeile",tableFont:"Statistik-Schrift",tableTeamFont:"Team-Schrift Tabelle",tableAlign:"Statistik-Ausrichtung",reset:"Standard-Layout",preview:"Vorschau"},\nes:{layout:"Layout",layoutSub:"Cada tamaño tiene su propia configuración de diseño.",small:"Small",medium:"Medium",large:"Large",teamWidth:"Ancho equipo",scoreWidth:"Ancho marcador",teamFont:"Tamaño equipo",scoreFont:"Tamaño marcador",logoSize:"Tamaño logo",logoGap:"Espacio logo",cardPaddingX:"Margen interior",teamAlign:"Alineación equipos",edge:"A los bordes",center:"Al centro",left:"Izquierda",right:"Derecha",dateWidth:"Ancho fecha",listTeamWidth:"Ancho equipo lista",listScoreWidth:"Ancho marcador lista",table:"Tabla",tableTeamWidth:"Ancho EQUIPO",wideWidth:"Primeras 4 estadísticas",narrowWidth:"Últimas 3 estadísticas",headerFont:"Cabecera",tableFont:"Estadísticas",tableTeamFont:"Equipo en tabla",tableAlign:"Alineación estadísticas",reset:"Restablecer Layout",preview:"Vista previa"}\n};\nfunction lt(s,k){const l=s.language||"en";return(LAYOUT_TEXT[l]||LAYOUT_TEXT.en)[k]||LAYOUT_TEXT.en[k]||k}\nfunction selectField(id,label,value,items){return `<div class="field"><label for="${id}">${esc(label)}</label><select id="${id}">${items.map(([v,t])=>`<option value="${esc(v)}" ${v===value?"selected":""}>${esc(t)}</option>`).join("")}</select></div>`}\n'''
pos=s.index('function html(s)')
s=s[:pos]+insert+s[pos:]

# Add layout navigation on home
old_home='''<div class="sectionTitle">${esc(L.appearance)}</div><div class="card">${nav("appearance","🎨",L.appearance,s.theme==="custom"?H.customTheme:s.theme)}</div><div class="sectionTitle">${esc(L.tools)}</div>'''
assert old_home in s
new_home='''<div class="sectionTitle">${esc(L.appearance)}</div><div class="card">${nav("appearance","🎨",L.appearance,s.theme==="custom"?H.customTheme:s.theme)}</div><div class="sectionTitle">${esc(lt(s,"layout"))}</div><div class="card">${nav("layout","📐",lt(s,"layout"),lt(s,"layoutSub"))}</div><div class="sectionTitle">${esc(L.tools)}</div>'''
s=s.replace(old_home,new_home,1)

# Layout screens inserted before appearance screen.
marker='<div class="screen" id="appearance">'
assert marker in s
layout_html='''<div class="screen" id="layout">${back}<div class="screenTitle">📐 ${esc(lt(s,"layout"))}</div><div class="screenSub">${esc(lt(s,"layoutSub"))}</div><div class="card">${nav("layoutSmall","▣",lt(s,"small"))}${nav("layoutMedium","▰",lt(s,"medium"))}${nav("layoutLarge","▦",lt(s,"large"))}</div></div>\n<div class="screen" id="layoutSmall">${back.replace("showScreen('home')","showScreen('layout')")}<div class="screenTitle">▣ ${esc(lt(s,"small"))}</div><button class="previewBtn presetBtn" onclick="preview('small')">👁 ${esc(lt(s,"preview"))}</button><div class="card">${field("layoutSmallTeamWidth",lt(s,"teamWidth"),s.layout.small.teamWidth,"number",'min="48" max="150"')}${field("layoutSmallScoreWidth",lt(s,"scoreWidth"),s.layout.small.scoreWidth,"number",'min="14" max="70"')}${field("layoutSmallTeamFont",lt(s,"teamFont"),s.layout.small.teamFont,"number",'min="7" max="15"')}${field("layoutSmallScoreFont",lt(s,"scoreFont"),s.layout.small.scoreFont,"number",'min="10" max="26"')}${field("layoutSmallLogoSize",lt(s,"logoSize"),s.layout.small.logoSize,"number",'min="8" max="24"')}${field("layoutSmallLogoGap",lt(s,"logoGap"),s.layout.small.logoGap,"number",'min="0" max="10"')}${field("layoutSmallCardPaddingX",lt(s,"cardPaddingX"),s.layout.small.cardPaddingX,"number",'min="0" max="18"')}${selectField("layoutSmallTeamAlign",lt(s,"teamAlign"),s.layout.small.teamAlign,[["edge",lt(s,"edge")],["center",lt(s,"center")],["left",lt(s,"left")],["right",lt(s,"right")]])}</div><button class="actionBtn secondary presetBtn" onclick="resetLayout('small')">↺ ${esc(lt(s,"reset"))}</button></div>\n<div class="screen" id="layoutMedium">${back.replace("showScreen('home')","showScreen('layout')")}<div class="screenTitle">▰ ${esc(lt(s,"medium"))}</div><button class="previewBtn presetBtn" onclick="preview('medium')">👁 ${esc(lt(s,"preview"))}</button><div class="card">${field("layoutMediumTeamWidth",lt(s,"teamWidth"),s.layout.medium.teamWidth,"number",'min="48" max="150"')}${field("layoutMediumScoreWidth",lt(s,"scoreWidth"),s.layout.medium.scoreWidth,"number",'min="14" max="70"')}${field("layoutMediumTeamFont",lt(s,"teamFont"),s.layout.medium.teamFont,"number",'min="7" max="15"')}${field("layoutMediumScoreFont",lt(s,"scoreFont"),s.layout.medium.scoreFont,"number",'min="10" max="26"')}${field("layoutMediumLogoSize",lt(s,"logoSize"),s.layout.medium.logoSize,"number",'min="8" max="24"')}${field("layoutMediumLogoGap",lt(s,"logoGap"),s.layout.medium.logoGap,"number",'min="0" max="10"')}${field("layoutMediumCardPaddingX",lt(s,"cardPaddingX"),s.layout.medium.cardPaddingX,"number",'min="0" max="18"')}${field("layoutMediumListDateWidth",lt(s,"dateWidth"),s.layout.medium.listDateWidth,"number",'min="30" max="60"')}${field("layoutMediumListTeamWidth",lt(s,"listTeamWidth"),s.layout.medium.listTeamWidth,"number",'min="72" max="135"')}${field("layoutMediumListScoreWidth",lt(s,"listScoreWidth"),s.layout.medium.listScoreWidth,"number",'min="36" max="70"')}${selectField("layoutMediumTeamAlign",lt(s,"teamAlign"),s.layout.medium.teamAlign,[["edge",lt(s,"edge")],["center",lt(s,"center")],["left",lt(s,"left")],["right",lt(s,"right")]])}</div><button class="actionBtn secondary presetBtn" onclick="resetLayout('medium')">↺ ${esc(lt(s,"reset"))}</button></div>\n<div class="screen" id="layoutLarge">${back.replace("showScreen('home')","showScreen('layout')")}<div class="screenTitle">▦ ${esc(lt(s,"large"))}</div><button class="previewBtn presetBtn" onclick="preview('large')">👁 ${esc(lt(s,"preview"))}</button><div class="sectionTitle">Match card</div><div class="card">${field("layoutLargeTeamWidth",lt(s,"teamWidth"),s.layout.large.teamWidth,"number",'min="48" max="150"')}${field("layoutLargeScoreWidth",lt(s,"scoreWidth"),s.layout.large.scoreWidth,"number",'min="14" max="70"')}${field("layoutLargeTeamFont",lt(s,"teamFont"),s.layout.large.teamFont,"number",'min="7" max="15"')}${field("layoutLargeScoreFont",lt(s,"scoreFont"),s.layout.large.scoreFont,"number",'min="10" max="26"')}${field("layoutLargeLogoSize",lt(s,"logoSize"),s.layout.large.logoSize,"number",'min="8" max="24"')}${field("layoutLargeLogoGap",lt(s,"logoGap"),s.layout.large.logoGap,"number",'min="0" max="10"')}${field("layoutLargeCardPaddingX",lt(s,"cardPaddingX"),s.layout.large.cardPaddingX,"number",'min="0" max="18"')}${selectField("layoutLargeTeamAlign",lt(s,"teamAlign"),s.layout.large.teamAlign,[["edge",lt(s,"edge")],["center",lt(s,"center")],["left",lt(s,"left")],["right",lt(s,"right")]])}</div><div class="sectionTitle">${esc(lt(s,"table"))}</div><div class="card">${field("layoutLargeTableTeamWidth",lt(s,"tableTeamWidth"),s.layout.large.tableTeamWidth,"number",'min="82" max="135"')}${field("layoutLargeTableWideWidth",lt(s,"wideWidth"),s.layout.large.tableWideWidth,"number",'min="24" max="38"')}${field("layoutLargeTableNarrowWidth",lt(s,"narrowWidth"),s.layout.large.tableNarrowWidth,"number",'min="18" max="32"')}${field("layoutLargeTableHeaderFont",lt(s,"headerFont"),s.layout.large.tableHeaderFont,"number",'min="7" max="12"')}${field("layoutLargeTableFont",lt(s,"tableFont"),s.layout.large.tableFont,"number",'min="8" max="14"')}${field("layoutLargeTableTeamFont",lt(s,"tableTeamFont"),s.layout.large.tableTeamFont,"number",'min="9" max="14"')}${selectField("layoutLargeTableAlign",lt(s,"tableAlign"),s.layout.large.tableAlign,[["center",lt(s,"center")],["right",lt(s,"right")]])}</div><div class="sectionTitle">Lists</div><div class="card">${field("layoutLargeListDateWidth",lt(s,"dateWidth"),s.layout.large.listDateWidth,"number",'min="30" max="60"')}${field("layoutLargeListTeamWidth",lt(s,"listTeamWidth"),s.layout.large.listTeamWidth,"number",'min="72" max="135"')}${field("layoutLargeListScoreWidth",lt(s,"listScoreWidth"),s.layout.large.listScoreWidth,"number",'min="36" max="70"')}</div><button class="actionBtn secondary presetBtn" onclick="resetLayout('large')">↺ ${esc(lt(s,"reset"))}</button></div>\n'''
s=s.replace(marker,layout_html+marker,1)

# WebView state: collect nested layout values + reset function.
old_collect="for(const k of['maxMatches','refreshMinutes']){const e=document.getElementById(k);if(e)z[k]=Number(e.value)}"
