new_collect=old_collect+";z.layout=JSON.parse(JSON.stringify(state.layout||"+"LAYOUT_DEFAULTS"+"));const map={small:['TeamWidth','ScoreWidth','TeamFont','ScoreFont','LogoSize','LogoGap','CardPaddingX'],medium:['TeamWidth','ScoreWidth','TeamFont','ScoreFont','LogoSize','LogoGap','CardPaddingX','ListDateWidth','ListTeamWidth','ListScoreWidth'],large:['TeamWidth','ScoreWidth','TeamFont','ScoreFont','LogoSize','LogoGap','CardPaddingX','ListDateWidth','ListTeamWidth','ListScoreWidth','TableTeamWidth','TableWideWidth','TableNarrowWidth','TableHeaderFont','TableFont','TableTeamFont']};for(const [f,keys] of Object.entries(map)){for(const suffix of keys){const id='layout'+f[0].toUpperCase()+f.slice(1)+suffix,e=document.getElementById(id);if(e){const key=suffix[0].toLowerCase()+suffix.slice(1);z.layout[f][key]=Number(e.value)}}const ae=document.getElementById('layout'+f[0].toUpperCase()+f.slice(1)+'TeamAlign');if(ae)z.layout[f].teamAlign=ae.value}const ta=document.getElementById('layoutLargeTableAlign');if(ta)z.layout.large.tableAlign=ta.value"
